  "codebook": {
    "clarification": "Include as credit-claiming: (1) announcements of federal grants, appropriations, or funding directed to the senator's state or its institutions; (2) announcements of favorable federal decisions, designations, projects, missions, disaster declarations, or appointments benefiting the state, when the senator's office delivers the news or claims a role; (3) statements highlighting the senator's own legislative products - bills introduced, sponsored, or cosponsored, amendments adopted, provisions included in larger bills, and laws authored - framed as actions taken on behalf of constituents; (4) statements linking the senator's request, letter, appeal, or advocacy to a subsequent federal action; (5) explicit retrospective claims such as 'I helped secure,' 'I authored,' 'my amendment,' 'a priority of mine,' or 'played a key role in.' Shared or partial credit (e.g., delegations, bipartisan pairs) still counts.",
    "definition": "Credit-claiming occurs when a senator claims, explicitly or implicitly, personal or shared responsibility for concrete governmental benefits, actions, or accomplishments that advantage their state, constituents, or favored causes. This includes securing or announcing federal funds, grants, projects, designations, or favorable federal decisions for the state; authoring, sponsoring, or passing legislation or amendments; and claiming a causal or instrumental role (through requests, letters, amendments, or advocacy) in producing a governmental outcome.",
    "negative_clarification": "Do not code as credit-claiming: (1) pure position statements explaining votes or stances on pending issues; (2) criticism of the administration, opposing party, or foreign actors; (3) tributes, obituaries, commemorations, and ceremonial recognitions of others; (4) announcements of town meetings or similar events; (5) awards or honors, whether given to constituents or received by the senator, that do not involve governmental benefits; (6) advocacy, demands, or pledges regarding pending outcomes ('I will continue to fight') where no benefit has been delivered; (7) reactions to external events in which the senator's own bill is mentioned only secondarily; (8) oversight or hearing participation without a claimed accomplishment.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Kerry's statement attacks the Bush administration's handling of the Dubai ports deal and port security; it is criticism and position-taking with no claim of responsibility for any benefit."
      },
      {
        "document_id": "3501",
        "explanation": "Tester expresses disappointment and pledges to 'continue to fight' for Malmstrom; advocacy toward a pending outcome without any delivered benefit is not credit-claiming."
      },
      {
        "document_id": "597",
        "explanation": "Lugar presents a health and fitness award honoring community groups; ceremonial recognition of others involves no claim of governmental benefits or accomplishments."
      }
    ],
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Dorgan announces a federal designation for Bismarck State College and explicitly notes he authored the legislation that created the designation - both announcing a benefit and claiming causal credit."
      },
      {
        "document_id": "2318",
        "explanation": "Durbin uses explicit first-person credit claims ('I helped secure an expedited environmental review... facilitated the return of the project to the national priority list for federal funding') even within a letter pressing state officials."
      },
      {
        "document_id": "4585",
        "explanation": "Schumer announces federal fire grants to local departments and reinforces his role by noting he was among the first to advocate the grant program - a textbook funding-announcement credit claim."
      }
    ]
  }
}
